```javascript
const Koa = require('koa');
const Router = require('koa-router');
const multer = require('@koa/multer');
const path = require('path');
const fs = require('fs');
const { v4: uuidv4 } = require('uuid');

const app = new Koa();
const router = new Router();
const upload = multer({ dest: 'uploads/' });

// In-memory storage for image metadata
const images = {};

// Upload image endpoint
router.post('/upload', upload.single('file'), async (ctx) => {
  try {
    const file = ctx.file;
    if (!file) {
      ctx.status = 400;
      ctx.body = { error: 'No file uploaded' };
      return;
    }

    const imageId = uuidv4();
    images[imageId] = {
      path: file.path,
      mimetype: file.mimetype,
    };

    ctx.status = 200;
    ctx.body = { id: imageId };
  } catch (error) {
    ctx.status = 500;
    ctx.body = { error: 'Internal server error' };
  }
});

// Share image endpoint
router.get('/images/:imageId', async (ctx) => {
  try {
    const imageId = ctx.params.imageId;
    const image = images[imageId];

    if (!image) {
      ctx.status = 404;
      ctx.body = { error: 'Image not found' };
      return;
    }

    ctx.type = image.mimetype;
    ctx.body = fs.createReadStream(image.path);
  } catch (error) {
    ctx.status = 500;
    ctx.body = { error: 'Internal server error' };
  }
});

app.use(router.routes()).use(router.allowedMethods());

app.listen(5000, '0.0.0.0', () => {
  console.log('Server running on http://0.0.0.0:5000');
});
```

